"""Dispatch planning utilities for the local build queue.

This module is shared by the command-line queue inspector and the background
dispatcher. Planning is deliberately side-effect free: callers can preview the
same candidate set several times before committing a dispatch transaction.

A pending job is represented by a tuple (job_id, priority, cost). Job identifiers
are unique strings. Higher integer priority means more urgent work. Cost is a
non-negative integer number of worker credits. The incoming order is the enqueue
order and is authoritative when two jobs have equal priority.

The scheduler has a greedy policy, not a knapsack policy: visit each candidate in
priority order, accept it if its cost fits the credits still available, otherwise
continue looking. In particular, an oversized job must not block a smaller job.
A zero-cost job is eligible even when no credits remain. Returned identifiers
must be in the order in which the candidates were accepted.

The surrounding API still returns immutable tuples in its snapshots. select_jobs
is an older public helper and returns a plain list of identifiers. Keep that
contract so callers do not need to change their serialization.

Tenant quotas, queue persistence, locks, wall-clock deadlines, and execution are
owned by the dispatcher. This module only calculates a deterministic plan. It
must never modify the candidates supplied by a caller.
"""

from dataclasses import dataclass
from typing import Iterable, Mapping, Optional, Sequence

SCHEMA_VERSION = 3
DEFAULT_WINDOW_SECONDS = 60
MAX_REPORT_ROWS = 200
PRIORITY_LABELS = {30: "urgent", 20: "normal", 10: "background"}
TERMINAL_STATES = frozenset(("finished", "failed", "cancelled"))


@dataclass(frozen=True)
class QueueRecord:
    job_id: str
    tenant: str
    priority: int
    cost: int
    enqueued_sequence: int
    state: str = "pending"
    description: str = ""


@dataclass(frozen=True)
class QueueSnapshot:
    revision: int
    records: tuple
    available_credits: int
    reserved_credits: int
    paused_tenants: tuple


@dataclass(frozen=True)
class DispatchPlan:
    revision: int
    chosen_ids: tuple
    credits_before: int
    credits_after: int
    skipped_ids: tuple


def validate_record(record):
    """Reject inconsistent records before they enter the durable queue."""
    if not record.job_id:
        raise ValueError("job_id must be non-empty")
    if not record.tenant:
        raise ValueError("tenant must be non-empty")
    if not isinstance(record.priority, int):
        raise ValueError("priority must be an integer")
    if not isinstance(record.cost, int) or record.cost < 0:
        raise ValueError("cost must be a non-negative integer")
    if record.enqueued_sequence < 0:
        raise ValueError("enqueued_sequence must be non-negative")
    if record.state not in ("pending", "running", *TERMINAL_STATES):
        raise ValueError("unrecognized queue state")
    return record


def validate_snapshot(snapshot):
    """Validate once at the input boundary, never in the selection loop."""
    if snapshot.revision < 0:
        raise ValueError("revision must be non-negative")
    if snapshot.available_credits < 0 or snapshot.reserved_credits < 0:
        raise ValueError("credit counters must be non-negative")
    seen = set()
    for record in snapshot.records:
        validate_record(record)
        if record.job_id in seen:
            raise ValueError("duplicate job identifier")
        seen.add(record.job_id)
    return snapshot


def pending_records(snapshot, tenant=None):
    """Preserve arrival order while filtering the materialized snapshot."""
    records = [
        record
        for record in snapshot.records
        if record.state == "pending"
        and (tenant is None or record.tenant == tenant)
    ]
    return tuple(sorted(records, key=lambda record: record.enqueued_sequence))


def candidate_tuples(snapshot):
    """Convert records to the stable public selection representation."""
    blocked = set(snapshot.paused_tenants)
    return [
        (record.job_id, record.priority, record.cost)
        for record in pending_records(snapshot)
        if record.tenant not in blocked
    ]


def select_jobs(jobs, budget):
    """Return a deterministic greedy plan without modifying jobs.

    This implementation predates support for zero-cost jobs and mixed priority.
    Replace only this function; the caller and snapshot contracts stay fixed.
    """
    selected = []
    remaining = budget
    for job_id, priority, cost in jobs:
        if remaining <= 0:
            break
        if cost > remaining:
            break
        selected.append(job_id)
        remaining -= cost
    return selected


def make_dispatch_plan(snapshot):
    """Build a preview against one revision; committing is handled elsewhere."""
    validate_snapshot(snapshot)
    candidates = candidate_tuples(snapshot)
    free_credits = max(0, snapshot.available_credits - snapshot.reserved_credits)
    chosen = select_jobs(candidates, free_credits)
    chosen_set = set(chosen)
    chosen_cost = sum(cost for job_id, _, cost in candidates if job_id in chosen_set)
    skipped = tuple(job_id for job_id, _, _ in candidates if job_id not in chosen_set)
    return DispatchPlan(
        revision=snapshot.revision,
        chosen_ids=tuple(chosen),
        credits_before=free_credits,
        credits_after=free_credits - chosen_cost,
        skipped_ids=skipped,
    )


def plan_is_current(plan, snapshot):
    """A caller must check the revision again inside its commit transaction."""
    return plan.revision == snapshot.revision


def apply_preview(snapshot, plan):
    """Return a hypothetical snapshot for the inspector, without persistence."""
    if not plan_is_current(plan, snapshot):
        raise ValueError("plan revision does not match snapshot revision")
    selected = set(plan.chosen_ids)
    revised = []
    for record in snapshot.records:
        next_state = "running" if record.job_id in selected else record.state
        revised.append(
            QueueRecord(
                record.job_id,
                record.tenant,
                record.priority,
                record.cost,
                record.enqueued_sequence,
                next_state,
                record.description,
            )
        )
    return QueueSnapshot(
        snapshot.revision,
        tuple(revised),
        snapshot.available_credits,
        snapshot.reserved_credits + plan.credits_before - plan.credits_after,
        snapshot.paused_tenants,
    )


def describe_priority(priority):
    """Retain custom priorities rather than silently rounding them to a band."""
    if priority in PRIORITY_LABELS:
        return PRIORITY_LABELS[priority]
    return "custom:" + str(priority)


def queue_counts(snapshot):
    counts = {"pending": 0, "running": 0, "finished": 0, "failed": 0, "cancelled": 0}
    for record in snapshot.records:
        counts[record.state] += 1
    return counts


def credit_summary(snapshot):
    pending_cost = sum(record.cost for record in snapshot.records if record.state == "pending")
    running_cost = sum(record.cost for record in snapshot.records if record.state == "running")
    return {
        "available": snapshot.available_credits,
        "reserved": snapshot.reserved_credits,
        "free": max(0, snapshot.available_credits - snapshot.reserved_credits),
        "pending_cost": pending_cost,
        "running_cost": running_cost,
    }


def tenant_summary(snapshot):
    """Report tenant demand independently of the global dispatch decision."""
    grouped = {}
    for record in snapshot.records:
        row = grouped.setdefault(record.tenant, {"pending": 0, "running": 0, "pending_cost": 0})
        if record.state == "pending":
            row["pending"] += 1
            row["pending_cost"] += record.cost
        elif record.state == "running":
            row["running"] += 1
    return [
        {"tenant": tenant, **grouped[tenant]}
        for tenant in sorted(grouped)
    ]


def record_to_dict(record):
    return {
        "job_id": record.job_id,
        "tenant": record.tenant,
        "priority": record.priority,
        "cost": record.cost,
        "enqueued_sequence": record.enqueued_sequence,
        "state": record.state,
        "description": record.description,
    }


def snapshot_to_dict(snapshot):
    return {
        "schema_version": SCHEMA_VERSION,
        "revision": snapshot.revision,
        "records": [record_to_dict(record) for record in snapshot.records],
        "available_credits": snapshot.available_credits,
        "reserved_credits": snapshot.reserved_credits,
        "paused_tenants": list(snapshot.paused_tenants),
    }


def plan_to_dict(plan):
    return {
        "revision": plan.revision,
        "chosen_ids": list(plan.chosen_ids),
        "credits_before": plan.credits_before,
        "credits_after": plan.credits_after,
        "skipped_ids": list(plan.skipped_ids),
    }


def record_from_dict(value):
    """Migration lives here so the core scheduling rule stays uncomplicated."""
    record = QueueRecord(
        job_id=value["job_id"],
        tenant=value.get("tenant", "default"),
        priority=value.get("priority", 20),
        cost=value["cost"],
        enqueued_sequence=value["enqueued_sequence"],
        state=value.get("state", "pending"),
        description=value.get("description", ""),
    )
    return validate_record(record)


def snapshot_from_dict(value):
    version = value.get("schema_version", 1)
    if version not in (1, 2, 3):
        raise ValueError("unsupported snapshot schema")
    snapshot = QueueSnapshot(
        revision=value["revision"],
        records=tuple(record_from_dict(record) for record in value["records"]),
        available_credits=value["available_credits"],
        reserved_credits=value.get("reserved_credits", 0),
        paused_tenants=tuple(value.get("paused_tenants", ())),
    )
    return validate_snapshot(snapshot)


def report_rows(snapshot, limit=MAX_REPORT_ROWS):
    """The inspector is ordered by arrival, even though selection is not."""
    if limit < 0:
        raise ValueError("report limit must be non-negative")
    ordered = sorted(snapshot.records, key=lambda record: record.enqueued_sequence)
    rows = []
    for record in ordered[:limit]:
        rows.append(
            {
                "id": record.job_id,
                "tenant": record.tenant,
                "priority": describe_priority(record.priority),
                "cost": record.cost,
                "state": record.state,
                "description": record.description,
            }
        )
    return rows


def summarize_plan(snapshot, plan):
    """Construct a stable human-facing receipt without changing the plan."""
    by_id = {record.job_id: record for record in snapshot.records}
    return {
        "revision": plan.revision,
        "selected": [
            {
                "id": job_id,
                "tenant": by_id[job_id].tenant,
                "priority": describe_priority(by_id[job_id].priority),
                "cost": by_id[job_id].cost,
            }
            for job_id in plan.chosen_ids
        ],
        "remaining_credits": plan.credits_after,
        "waiting": len(plan.skipped_ids),
        "paused_tenants": list(snapshot.paused_tenants),
    }


def jobs_for_tenant(snapshot, tenant):
    return tuple(record for record in snapshot.records if record.tenant == tenant)


def oldest_pending_sequence(snapshot):
    sequences = [
        record.enqueued_sequence
        for record in snapshot.records
        if record.state == "pending"
    ]
    return min(sequences) if sequences else None


def normalize_paused_tenants(tenants):
    """Canonicalize configuration only; this does not reorder any jobs."""
    return tuple(sorted(set(tenant for tenant in tenants if tenant)))


def replace_capacity(snapshot, capacity):
    if capacity < 0:
        raise ValueError("capacity must be non-negative")
    return QueueSnapshot(
        snapshot.revision + 1,
        snapshot.records,
        capacity,
        snapshot.reserved_credits,
        snapshot.paused_tenants,
    )


def pending_cost_by_priority(snapshot):
    totals = {}
    for record in snapshot.records:
        if record.state == "pending":
            totals[record.priority] = totals.get(record.priority, 0) + record.cost
    return tuple((priority, totals[priority]) for priority in sorted(totals, reverse=True))


def expired_pending_ids(snapshot, oldest_allowed_sequence):
    """A separate retention policy; selection never discards pending records."""
    return tuple(
        record.job_id
        for record in snapshot.records
        if record.state == "pending"
        and record.enqueued_sequence < oldest_allowed_sequence
    )


def explanation_for_skipped(snapshot, plan):
    """Explain only facts in the snapshot; do not infer a future dispatch time."""
    selected = set(plan.chosen_ids)
    paused = set(snapshot.paused_tenants)
    explanations = []
    for record in pending_records(snapshot):
        if record.job_id in selected:
            continue
        reason = "tenant paused" if record.tenant in paused else "not in current plan"
        explanations.append((record.job_id, reason))
    return tuple(explanations)


def empty_snapshot(capacity=0):
    return QueueSnapshot(0, (), capacity, 0, ())


def merge_new_records(snapshot, new_records):
    """Merge admission results without changing the arrival order of old jobs."""
    records = list(snapshot.records)
    seen = {record.job_id for record in records}
    last_sequence = max((record.enqueued_sequence for record in records), default=-1)
    for record in new_records:
        validate_record(record)
        if record.job_id in seen:
            raise ValueError("job identifier already exists")
        if record.enqueued_sequence <= last_sequence:
            raise ValueError("new arrivals must have increasing sequence numbers")
        records.append(record)
        seen.add(record.job_id)
        last_sequence = record.enqueued_sequence
    return QueueSnapshot(
        snapshot.revision + 1,
        tuple(records),
        snapshot.available_credits,
        snapshot.reserved_credits,
        snapshot.paused_tenants,
    )
